import { Version } from '@game-studio/utilities';
import { IDeviceSystem } from '../types';

export abstract class DeviceSystem<T extends string> implements IDeviceSystem<T> {
    public readonly name: T | 'UNKNOWN';
    public readonly version: Version;

    constructor(name?: T, version?: string) {
        this.name = name as T ?? 'UNKNOWN';
        this.version = new Version(version);
    }

    public is(name: T): boolean {
        return this.name === 'UNKNOWN' ? false : this.name.includes(name);
    }

    public isAnyOf(...names: T[]): boolean {
        if (this.name === 'UNKNOWN') {
            return false;
        }
        return names.some((nameToCheck) => this.is(nameToCheck));
    }
}